//------------------------------------------------------------------------------
//
//  Stress test of the scmRTOS Cortex-M port in the cm4sim model.
//
//  Interrupts (random, asynchronous, generated by the model):
//    IRQ0 A  priority  6  OS ISR: TEventFlag::signal_isr()
//    IRQ1 B  priority  9  OS ISR: channel::try_push() of a sequence number
//    IRQ2 H  priority  1  no OS services: measures its own latency, records
//                         what it preempted
//    IRQ3 M  priority  3  no OS services: long handler, may be preempted by H
//  SysTick priority 14 (port default), PendSV 15.
//
//  With TEST_DI_LEVEL = 5 (scmRTOS_OS_DI_LEVEL) H and M are above the OS level:
//  the test requires that H is never delayed and that it preempts OS critical
//  sections and PendSV. With TEST_DI_LEVEL = 0 (old PRIMASK scheme) the same
//  program runs and reports the latency for comparison.
//
//  Processes check: event flag, channel order, mutex exclusion, message
//  ping-pong, sleep timeouts, and preservation of process registers
//  (integer and, with FPU, floating point) across context switches.
//
//  Exit code 0 - pass.
//
//------------------------------------------------------------------------------

#include <scmRTOS.h>

#ifndef TEST_DI_LEVEL
#define TEST_DI_LEVEL 0
#endif

// priority grouping (AIRCR.PRIGROUP): 3 - 4 bits of group priority (STM32 NVIC_PRIORITYGROUP_4)
#ifndef TEST_PRIGROUP
#define TEST_PRIGROUP 3
#endif

// allowed variation of H latency, instructions (erratum 837070 workaround masks
// all interrupts for 3 instructions)
#ifndef TEST_LAT_JITTER
#if defined scmRTOS_CM7_R0P1_ERRATUM_837070 && scmRTOS_CM7_R0P1_ERRATUM_837070 == 1
#define TEST_LAT_JITTER 3
#else
#define TEST_LAT_JITTER 1
#endif
#endif

#ifndef TEST_TICKS
#define TEST_TICKS 3000
#endif

//------------------------------------------------------------------------------
//  Model device
namespace dev
{
    volatile uint32_t * const base = (volatile uint32_t *)0x40000000UL;
    inline void putc(char c) { base[0] = (uint8_t)c; }
    [[noreturn]] inline void exit(uint32_t code) { base[1] = code; for(;;) { } }
    inline uint32_t cycle() { return base[2]; }
    inline void rand_irqs(uint32_t mask) { base[4] = mask; }
    inline uint32_t pend_cycle(int exc) { return base[0x40 + exc]; }
}

static void puts_(const char *s) { while(*s) dev::putc(*s++); }
static void putu(uint32_t v)
{
    char b[11]; int i = 10; b[i] = 0;
    do { b[--i] = '0' + v % 10; v /= 10; } while(v);
    puts_(&b[i]);
}
static void kv(const char *k, uint32_t v) { puts_(k); puts_("="); putu(v); puts_(" "); }

[[noreturn]] static void fail(const char *what, uint32_t a = 0, uint32_t b = 0)
{
    puts_("\nFAIL: "); puts_(what); puts_(" "); putu(a); puts_(" "); putu(b); puts_("\n");
    dev::exit(1);
}

extern "C" [[noreturn]] void test_isr_priority_error()
{
    puts_("ISR priority check fired\n");
#if defined TEST_BAD_ISR || defined TEST_EXPECT_CHECK
    dev::exit(0);
#else
    dev::exit(1);
#endif
}

//------------------------------------------------------------------------------
//  Registers
#define REG32(a) (*(volatile uint32_t *)(a))
#define REG8(a)  (*(volatile uint8_t *)(a))

static inline uint32_t get_basepri() { uint32_t v; __asm__ volatile ("MRS %0, BASEPRI" : "=r"(v)); return v; }
static inline uint32_t get_primask() { uint32_t v; __asm__ volatile ("MRS %0, PRIMASK" : "=r"(v)); return v; }

enum { IRQ_A = 0, IRQ_B = 1, IRQ_H = 2, IRQ_M = 3 };
#ifndef TEST_PRIO_A
#define TEST_PRIO_A 6
#endif
enum { PRIO_A = TEST_PRIO_A, PRIO_B = 9, PRIO_H = 1, PRIO_M = 3 };

// H preempts M only if it has higher group priority
#define H_OVER_M (((PRIO_H << 4) >> (TEST_PRIGROUP + 1)) < ((PRIO_M << 4) >> (TEST_PRIGROUP + 1)))

//------------------------------------------------------------------------------
//  Statistics
static volatile uint32_t isr_a, isr_b, isr_b_full, isr_h, isr_m;
static volatile uint32_t h_lat_min = 0xFFFFFFFF, h_lat_max;
static volatile uint32_t m_lat_min = 0xFFFFFFFF, m_lat_max;
static volatile uint32_t h_in_cs, h_in_pendsv, h_in_m, h_in_os_isr, m_in_cs;
static volatile uint32_t h_m_active;           // M is running
static volatile uint32_t os_isr_active;        // an OS ISR (A or B) is running
static volatile uint32_t b_seq;
static volatile uint32_t switches;

#ifndef __SOFTFP__
static volatile float h_facc = 1.0f;
#endif

//------------------------------------------------------------------------------
//  OS objects
OS::TEventFlag             ef_a;
OS::channel<uint32_t, 8>   ch_b;
OS::TMutex                 mtx;
OS::message<uint32_t>      msg_req, msg_ack;

static volatile uint32_t shared_x, shared_y;
static volatile uint32_t cnt_ef, cnt_ch, cnt_mtx[2], cnt_msg, cnt_sleep;

//------------------------------------------------------------------------------
//  Interrupt handlers
extern "C" void IRQ0_Handler()                  // A: OS ISR
{
    OS::TISRW isr;
    os_isr_active = os_isr_active + 1;
    isr_a = isr_a + 1;
    ef_a.signal_isr();
    os_isr_active = os_isr_active - 1;
}

extern "C" void IRQ1_Handler()                  // B: OS ISR
{
    OS::TISRW isr;
    os_isr_active = os_isr_active + 1;
    isr_b = isr_b + 1;
    uint32_t seq = b_seq;
    if(ch_b.try_push(seq))
        b_seq = b_seq + 1;
    else
        isr_b_full = isr_b_full + 1;
    os_isr_active = os_isr_active - 1;
}

// work that clobbers caller-saved integer and FP registers
__attribute__((noinline)) static uint32_t scramble(uint32_t x)
{
    uint32_t a = x * 2654435761u, b = a ^ (a >> 13), c = b * 0x5bd1e995u, d = c + a;
#ifndef __SOFTFP__
    h_facc = h_facc * 1.0001f + 0.5f;
#endif
    return a ^ b ^ c ^ d;
}

extern "C" void IRQ2_Handler()                  // H: high priority, no OS services
{
    uint32_t now = dev::cycle();
    uint32_t lat = now - dev::pend_cycle(16 + IRQ_H);
    if(lat < h_lat_min) h_lat_min = lat;
    if(lat > h_lat_max) h_lat_max = lat;

#ifdef TEST_BAD_ISR
    OS::TISRW isr;                              // misuse: must be caught by the check
#endif

    if(get_basepri() != 0) h_in_cs = h_in_cs + 1;
    if(REG32(0xE000ED24) & (1u << 10)) h_in_pendsv = h_in_pendsv + 1;
    if(h_m_active) h_in_m = h_in_m + 1;
    if(os_isr_active) h_in_os_isr = h_in_os_isr + 1;
    isr_h = isr_h + 1;
    volatile uint32_t sink = scramble(now);
    (void)sink;
}

extern "C" void IRQ3_Handler()                  // M: medium-high priority, no OS services
{
    uint32_t now = dev::cycle();
    uint32_t lat = now - dev::pend_cycle(16 + IRQ_M);
    if(lat < m_lat_min) m_lat_min = lat;
    if(lat > m_lat_max) m_lat_max = lat;
    if(get_basepri() != 0) m_in_cs = m_in_cs + 1;

    h_m_active = 1;
    uint32_t x = now;
    for(int i = 0; i < 5; i++) x = scramble(x);
    // pend H by software: if H has higher group priority it must run at once
    uint32_t h0 = isr_h;
    REG32(0xE000E200) = 1u << IRQ_H;            // NVIC_ISPR0
    __asm__ volatile ("DSB\n ISB" ::: "memory");
    if(H_OVER_M && isr_h == h0) fail("H did not preempt M");
    if(!H_OVER_M && isr_h != h0) fail("H preempted M of the same group");
    for(int i = 0; i < 5; i++) x = scramble(x);
    h_m_active = 0;
    isr_m = isr_m + 1;
}

//------------------------------------------------------------------------------
//  Hooks
void OS::system_timer_user_hook() { }
void OS::context_switch_user_hook() { switches = switches + 1; }
static volatile uint32_t idle_count;
void OS::idle_process_user_hook() { idle_count = idle_count + 1; }

//------------------------------------------------------------------------------
//  Register preservation check: x lives in registers across OS calls,
//  copy is kept in memory.
struct RegCheck
{
    volatile uint32_t mem;
    volatile float fmem;
};
static RegCheck rc[6];

#ifndef __SOFTFP__
#define FSTEP(f) ((f) * 1.5f + 1.0f)
#endif

static inline uint32_t step(uint32_t x) { return x * 1664525u + 1013904223u; }

static void check_reg(int id, uint32_t x)
{
    if(rc[id].mem != x) fail("register corrupted, process", id, x);
}

//------------------------------------------------------------------------------
//  Processes
typedef OS::process<OS::pr0, 1024> TProc0;
typedef OS::process<OS::pr1, 1024> TProc1;
typedef OS::process<OS::pr2, 1024> TProc2;
typedef OS::process<OS::pr3, 1024> TProc3;
typedef OS::process<OS::pr4, 1024> TProc4;
typedef OS::process<OS::pr5, 1024> TProc5;

TProc0 Proc0;
TProc1 Proc1;
TProc2 Proc2;
TProc3 Proc3;
TProc4 Proc4;
TProc5 Proc5;

static void report_and_exit();

// P0: waits for event flag from IRQ A; runs the test for TEST_TICKS ticks
template<> void TProc0::exec()
{
    if(get_basepri() != 0 || get_primask() != 0) fail("process started with interrupts masked", get_basepri(), get_primask());
    dev::rand_irqs((1u << IRQ_A) | (1u << IRQ_B) | (1u << IRQ_H) | (1u << IRQ_M));
    uint32_t x = 0x12345678;
#ifndef __SOFTFP__
    float f = 0.25f;
#endif
    for(;;)
    {
        x = step(x); rc[0].mem = x;
#ifndef __SOFTFP__
        f = FSTEP(f); if(f > 1.0e6f) f = 0.25f; rc[0].fmem = f;
#endif
        if(ef_a.wait(20))
            cnt_ef = cnt_ef + 1;
        check_reg(0, x);
#ifndef __SOFTFP__
        if(rc[0].fmem != f) fail("FP register corrupted, process", 0);
#endif
        if(OS::get_tick_count() >= TEST_TICKS)
            report_and_exit();
    }
}

// P1: reads channel filled by IRQ B, checks the order
template<> void TProc1::exec()
{
    uint32_t expect = 0, x = 0xCAFEBABE;
    for(;;)
    {
        x = step(x); rc[1].mem = x;
        uint32_t v;
        if(ch_b.pop(v, 30))
        {
            if(v != expect) fail("channel order", v, expect);
            expect++;
            cnt_ch = cnt_ch + 1;
        }
        check_reg(1, x);
    }
}

// P2, P3: mutex exclusion with sleeping inside the locked region
template<int N> [[noreturn]] static void mutex_proc(uint32_t seed)
{
    uint32_t x = seed;
#ifndef __SOFTFP__
    float f = 1.0f + N;
#endif
    for(;;)
    {
        x = step(x); rc[2 + N].mem = x;
#ifndef __SOFTFP__
        f = FSTEP(f); if(f > 1.0e6f) f = 1.0f; rc[2 + N].fmem = f;
#endif
        mtx.lock();
        uint32_t a = shared_x;
        shared_x = a + 1;
        if(x & 1) OS::sleep(1);
        if(shared_y != a) fail("mutex exclusion", shared_y, a);
        shared_y = a + 1;
        mtx.unlock();
        cnt_mtx[N] = cnt_mtx[N] + 1;
        OS::sleep(1 + (x >> 30));
        cnt_sleep = cnt_sleep + 1;
        check_reg(2 + N, x);
#ifndef __SOFTFP__
        if(rc[2 + N].fmem != f) fail("FP register corrupted, process", 2 + N);
#endif
    }
}

template<> void TProc2::exec() { mutex_proc<0>(0x1111); }
template<> void TProc3::exec() { mutex_proc<1>(0x2222); }

// P4 -> P5 request, P5 -> P4 acknowledge
template<> void TProc4::exec()
{
    uint32_t k = 0, x = 0x4444;
    for(;;)
    {
        x = step(x); rc[4].mem = x;
        msg_req = k;
        msg_req.send();
        if(!msg_ack.wait(1000)) fail("message ack timeout", k);
        uint32_t r; msg_ack.out(r);
        if(r != k + 1) fail("message value", r, k + 1);
        k += 2;
        cnt_msg = cnt_msg + 1;
        check_reg(4, x);
        if(x & 3) OS::sleep(1);
    }
}

static volatile uint32_t cnt_nested;

// Nested critical sections: the inner one must not unmask the outer one,
// and (BASEPRI mode) a section inside a higher user mask level must not
// lower it.
static void nested_critsect_check()
{
    {
        TCritSect outer;
        { TCritSect inner; }
        uint32_t n0 = isr_a + isr_b;
        for(volatile int i = 0; i < 60; i++) { }
        if(isr_a + isr_b != n0) fail("OS ISR ran inside the outer critical section");
    }
#if TEST_DI_LEVEL != 0
    if((PRIO_M << 4) >> (TEST_PRIGROUP + 1) < (TEST_DI_LEVEL << 4) >> (TEST_PRIGROUP + 1))   // M above the OS level
    {
        const uint32_t user_level = (uint32_t)PRIO_M << 4;     // user masks M too
        __asm__ volatile ("MSR BASEPRI, %0" : : "r"(user_level) : "memory");
        {
            TCritSect cs;
            if(get_basepri() != user_level) fail("critical section lowered the mask level", get_basepri());
            uint32_t m0 = isr_m;
            for(volatile int i = 0; i < 60; i++) { }
            if(isr_m != m0) fail("M ran inside the user mask level");
        }
        if(get_basepri() != user_level) fail("critical section did not restore the mask level", get_basepri());
        __asm__ volatile ("MSR BASEPRI, %0" : : "r"(0) : "memory");
    }
#endif
    cnt_nested = cnt_nested + 1;
}

template<> void TProc5::exec()
{
    uint32_t x = 0x5555;
    for(;;)
    {
        x = step(x); rc[5].mem = x;
        nested_critsect_check();
        if(msg_req.wait(200))
        {
            uint32_t v; msg_req.out(v);
            msg_ack = v + 1;
            msg_ack.send();
        }
        check_reg(5, x);
    }
}

static void report_and_exit()
{
    dev::rand_irqs(0);
#if defined TEST_BAD_ISR || defined TEST_EXPECT_CHECK
    fail("ISR priority check did not fire");
#endif
    puts_("di_level="); putu(TEST_DI_LEVEL); puts_(" ");
    kv("A", isr_a); kv("B", isr_b); kv("B_full", isr_b_full); kv("H", isr_h); kv("M", isr_m);
    kv("switches", switches); puts_("\n");
    kv("ef", cnt_ef); kv("ch", cnt_ch); kv("mtx0", cnt_mtx[0]); kv("mtx1", cnt_mtx[1]);
    kv("msg", cnt_msg); kv("sleep", cnt_sleep); kv("nested", cnt_nested); puts_("\n");
    kv("H_lat_min", h_lat_min); kv("H_lat_max", h_lat_max);
    kv("M_lat_min", m_lat_min); kv("M_lat_max", m_lat_max); puts_("\n");
    kv("H_in_os_cs", h_in_cs); kv("H_in_pendsv", h_in_pendsv); kv("H_in_M", h_in_m);
    kv("H_in_os_isr", h_in_os_isr); kv("M_in_os_cs", m_in_cs); puts_("\n");

    if(!isr_a || !isr_b || !isr_h || !isr_m) fail("some interrupt never ran");
    if(!cnt_ef || !cnt_ch || !cnt_mtx[0] || !cnt_mtx[1] || !cnt_msg || !cnt_nested) fail("some service never worked");
    // pushed == popped + queued; P1 may be preempted between pop() and its
    // counter update, IRQ B may still run after the generator is stopped
    {
        uint32_t pushed = isr_b - isr_b_full, seen = cnt_ch + ch_b.get_count();
        if(pushed < seen || pushed - seen > 2) fail("channel accounting", pushed, seen);
    }
    // group priorities: H preempts M only if they are in different groups
    const bool h_over_m = H_OVER_M;
    if(h_over_m && h_in_m < isr_m) fail("H did not preempt every M", h_in_m, isr_m);
    if(!h_over_m && h_in_m) fail("H preempted M of the same group");

#if TEST_DI_LEVEL != 0
    // above the OS level (by group priority): never masked by the OS
    const uint32_t gshift = TEST_PRIGROUP + 1;
    const uint32_t di_group = (uint32_t)(TEST_DI_LEVEL << 4) >> gshift;
    const bool h_above = (uint32_t)(PRIO_H << 4) >> gshift < di_group;
    const bool m_above = (uint32_t)(PRIO_M << 4) >> gshift < di_group;
    if(h_above)
    {
        if(h_over_m && h_lat_max - h_lat_min > TEST_LAT_JITTER) fail("H latency varies", h_lat_min, h_lat_max);   // else M may delay H
        if(!h_in_cs)     fail("H never preempted an OS critical section");
        if(!h_in_pendsv) fail("H never preempted PendSV");
        if(!h_in_os_isr) fail("H never preempted an OS ISR");
    }
    else if(h_in_cs) fail("H preempted an OS critical section though masked", h_in_cs);
    if(m_above && !m_in_cs) fail("M never preempted an OS critical section");
    if(!m_above && m_in_cs) fail("M preempted an OS critical section though masked", m_in_cs);
#else
    if(h_in_cs || m_in_cs) fail("BASEPRI used in PRIMASK mode");
    if(h_lat_max - h_lat_min <= 1) fail("H latency does not depend on the OS in PRIMASK mode?");
#endif
    puts_("PASS\n");
    dev::exit(0);
}

//------------------------------------------------------------------------------
int main()
{
    // priority grouping: TEST_PRIGROUP
    REG32(0xE000ED0C) = 0x05FA0000u | (TEST_PRIGROUP << 8);
#if TEST_PRIGROUP > 6
#error "TEST_PRIGROUP: at least one bit of group priority is needed"
#endif

    REG8(0xE000E400 + IRQ_A) = PRIO_A << 4;
    REG8(0xE000E400 + IRQ_B) = PRIO_B << 4;
    REG8(0xE000E400 + IRQ_H) = PRIO_H << 4;
    REG8(0xE000E400 + IRQ_M) = PRIO_M << 4;
    REG32(0xE000E100) = 0xF;                    // enable IRQ0..3

#if TEST_DI_LEVEL != 0
    // as if left by a boot loader: os_start() must clear it
    __asm__ volatile ("MSR BASEPRI, %0" : : "r"(TEST_DI_LEVEL << 4) : "memory");
#endif
    OS::run();
}
